NiriOutputConfigChanged::NiriOutputConfigChanged(Kind kind)
{
    switch (kind) {
    case Applied: m_wireName = QStringLiteral("Applied"); break;
    case OutputWasMissing: m_wireName = QStringLiteral("OutputWasMissing"); break;
    default: break;
    }
}
NiriOutputConfigChanged NiriOutputConfigChanged::fromWireName(const QString &name)
{
    NiriOutputConfigChanged result;
    result.m_wireName = name;
    return result;
}
NiriOutputConfigChanged::Kind NiriOutputConfigChanged::kind() const
{
    if (m_wireName == QStringLiteral("Applied")) return Applied;
    if (m_wireName == QStringLiteral("OutputWasMissing")) return OutputWasMissing;
    return Unknown;
}

namespace {
template <typename T, typename = void> struct HasInvalidReason : std::false_type {};
template <typename T> struct HasInvalidReason<T, std::void_t<decltype(std::declval<T>().invalidReason)>> : std::true_type {};
template <typename T>
QVariant invalidArgument(const NiriIpc::DecodeError &error)
{
    if constexpr (HasInvalidReason<T>::value) {
        T result;
        result.invalidReason = error.path + QStringLiteral(": ") + error.message;
        return QVariant::fromValue(result);
    } else {
        NiriInvalidArgument result;
        result.path = error.path;
        result.message = error.message;
        return QVariant::fromValue(result);
    }
}
template <typename T>
QVariant constructArgument(const NiriWire::WireValue &wire)
{
    T typed{};
    NiriIpc::DecodeError error;
    if (!NiriIpc::decode(wire, typed, &error, QStringLiteral("$"), NiriIpc::DecodeMode::Outbound))
        return invalidArgument<T>(error);
    return QVariant::fromValue(typed);
}
} // namespace

